-- Proposed consolidated PostgreSQL design. Not executed; no production policies supplied.
-- Reconcile with the previous workspace schema before adopting; do not deploy both as parallel graphs.
CREATE SCHEMA semester_workspace;
CREATE TABLE semester_workspace.tenants(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('personal','institution')));
CREATE TABLE semester_workspace.scopes(tenant_id uuid NOT NULL REFERENCES semester_workspace.tenants(id),id uuid NOT NULL,owner_id uuid NOT NULL,policy_id text NOT NULL,policy_version text NOT NULL,retention_policy_id text NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE semester_workspace.nodes(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text NOT NULL,scope_id uuid NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES semester_workspace.scopes(tenant_id,id));
CREATE TABLE semester_workspace.facts(tenant_id uuid NOT NULL,id uuid NOT NULL,node_id uuid NOT NULL,scope_id uuid NOT NULL,predicate text NOT NULL,value jsonb NOT NULL,source_binding_id uuid NOT NULL,source_record_id text NOT NULL,source_version text NOT NULL,authority_category text NOT NULL,classification text NOT NULL,verification_state text NOT NULL,observed_at timestamptz NOT NULL,source_updated_at timestamptz,freshness_policy_id uuid NOT NULL,supersedes_id uuid,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,node_id) REFERENCES semester_workspace.nodes(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES semester_workspace.scopes(tenant_id,id),FOREIGN KEY(tenant_id,supersedes_id) REFERENCES semester_workspace.facts(tenant_id,id));
-- source_binding_id and freshness_policy_id require the full reviewed source/freshness tables;
-- this design slice does not implement their authorization or validation.
CREATE TABLE semester_workspace.edges(tenant_id uuid NOT NULL,id uuid NOT NULL,from_id uuid NOT NULL,to_id uuid NOT NULL,relation_type text NOT NULL,scope_id uuid NOT NULL,source_fact_id uuid NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,from_id) REFERENCES semester_workspace.nodes(tenant_id,id),FOREIGN KEY(tenant_id,to_id) REFERENCES semester_workspace.nodes(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES semester_workspace.scopes(tenant_id,id),FOREIGN KEY(tenant_id,source_fact_id) REFERENCES semester_workspace.facts(tenant_id,id));
CREATE TABLE semester_workspace.courses(tenant_id uuid NOT NULL,node_id uuid NOT NULL,issuer_course_key text NOT NULL,catalog_version text NOT NULL,code text NOT NULL,title_fact_id uuid NOT NULL,credits_fact_id uuid NOT NULL,PRIMARY KEY(tenant_id,node_id),UNIQUE(tenant_id,issuer_course_key,catalog_version),FOREIGN KEY(tenant_id,node_id) REFERENCES semester_workspace.nodes(tenant_id,id),FOREIGN KEY(tenant_id,title_fact_id) REFERENCES semester_workspace.facts(tenant_id,id),FOREIGN KEY(tenant_id,credits_fact_id) REFERENCES semester_workspace.facts(tenant_id,id));
CREATE TABLE semester_workspace.terms(tenant_id uuid NOT NULL,id uuid NOT NULL,source_key text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,source_key),CHECK(ends_at>starts_at));
CREATE TABLE semester_workspace.sections(tenant_id uuid NOT NULL,node_id uuid NOT NULL,course_node_id uuid NOT NULL,term_id uuid NOT NULL,source_section_key text NOT NULL,PRIMARY KEY(tenant_id,node_id),UNIQUE(tenant_id,source_section_key,term_id),FOREIGN KEY(tenant_id,node_id) REFERENCES semester_workspace.nodes(tenant_id,id),FOREIGN KEY(tenant_id,course_node_id) REFERENCES semester_workspace.courses(tenant_id,node_id),FOREIGN KEY(tenant_id,term_id) REFERENCES semester_workspace.terms(tenant_id,id));
CREATE TABLE semester_workspace.prerequisite_rules(tenant_id uuid NOT NULL,id uuid NOT NULL,target_course_id uuid NOT NULL,rule_version text NOT NULL,source_fact_id uuid NOT NULL,catalog_version text NOT NULL,effective_from timestamptz NOT NULL,effective_until timestamptz,status text NOT NULL CHECK(status IN ('candidate','approved','superseded','revoked')),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,target_course_id,rule_version),FOREIGN KEY(tenant_id,target_course_id) REFERENCES semester_workspace.courses(tenant_id,node_id),FOREIGN KEY(tenant_id,source_fact_id) REFERENCES semester_workspace.facts(tenant_id,id),CHECK(effective_until IS NULL OR effective_until>effective_from));
CREATE TABLE semester_workspace.prerequisite_expressions(tenant_id uuid NOT NULL,rule_id uuid NOT NULL,id uuid NOT NULL,parent_id uuid,position integer NOT NULL CHECK(position>=0),operator text NOT NULL CHECK(operator IN ('all','any','course_completed','placement_met','permission_granted','credits_met')),required_course_id uuid,timing text CHECK(timing IN ('before_start','concurrent_allowed')),grade_policy_id text,threshold_policy_id text,PRIMARY KEY(tenant_id,rule_id,id),FOREIGN KEY(tenant_id,rule_id) REFERENCES semester_workspace.prerequisite_rules(tenant_id,id),FOREIGN KEY(tenant_id,rule_id,parent_id) REFERENCES semester_workspace.prerequisite_expressions(tenant_id,rule_id,id),FOREIGN KEY(tenant_id,required_course_id) REFERENCES semester_workspace.courses(tenant_id,node_id),CHECK(parent_id IS NULL OR parent_id<>id),CHECK((operator='course_completed' AND required_course_id IS NOT NULL AND timing IS NOT NULL) OR (operator<>'course_completed' AND required_course_id IS NULL)));
CREATE UNIQUE INDEX one_rule_root ON semester_workspace.prerequisite_expressions(tenant_id,rule_id) WHERE parent_id IS NULL;
CREATE TABLE semester_workspace.resources(tenant_id uuid NOT NULL,node_id uuid NOT NULL,resource_kind text NOT NULL CHECK(resource_kind IN ('note','file','reading','video','dataset','web_reference','practice_pack')),content_locator text NOT NULL,content_digest text,source_fact_id uuid NOT NULL,rights_policy_id text NOT NULL,source_access_mode text NOT NULL CHECK(source_access_mode IN ('owned_copy','linked','licensed_reference')),PRIMARY KEY(tenant_id,node_id),FOREIGN KEY(tenant_id,node_id) REFERENCES semester_workspace.nodes(tenant_id,id),FOREIGN KEY(tenant_id,source_fact_id) REFERENCES semester_workspace.facts(tenant_id,id));
CREATE TABLE semester_workspace.academic_evidence(tenant_id uuid NOT NULL,id uuid NOT NULL,student_principal_id uuid NOT NULL,course_node_id uuid,evidence_kind text NOT NULL CHECK(evidence_kind IN ('completed_credit','transfer_credit','placement','permission','current_enrollment','waiver')),source_fact_id uuid NOT NULL,decision_policy_id text NOT NULL,effective_from timestamptz NOT NULL,effective_until timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,course_node_id) REFERENCES semester_workspace.courses(tenant_id,node_id),FOREIGN KEY(tenant_id,source_fact_id) REFERENCES semester_workspace.facts(tenant_id,id));
CREATE TABLE semester_workspace.eligibility_evaluations(tenant_id uuid NOT NULL,id uuid NOT NULL,student_principal_id uuid NOT NULL,section_id uuid NOT NULL,rule_id uuid NOT NULL,rule_version text NOT NULL,input_manifest_digest text NOT NULL,evaluated_at timestamptz NOT NULL,result text NOT NULL CHECK(result IN ('satisfied','not_satisfied','unknown')),explanation jsonb NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,section_id) REFERENCES semester_workspace.sections(tenant_id,node_id),FOREIGN KEY(tenant_id,rule_id) REFERENCES semester_workspace.prerequisite_rules(tenant_id,id));
CREATE INDEX course_resource_lookup ON semester_workspace.edges(tenant_id,from_id,relation_type);
CREATE INDEX prereq_evidence_lookup ON semester_workspace.academic_evidence(tenant_id,student_principal_id,course_node_id);
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='semester_workspace' LOOP
EXECUTE format('ALTER TABLE semester_workspace.%I ENABLE ROW LEVEL SECURITY',t.tablename);
EXECUTE format('ALTER TABLE semester_workspace.%I FORCE ROW LEVEL SECURITY',t.tablename);
EXECUTE format('REVOKE ALL ON semester_workspace.%I FROM PUBLIC',t.tablename);
END LOOP; END $$;
-- Required before use: complete source/grant/audit/freshness FKs and tables, authentication,
-- restrictive role policies, immutable versions, typed edges, scope non-expansion,
-- expression leaf/group arity and acyclicity, policy-linked thresholds, allowed grade ordering,
-- pinned evaluation versions, no overlapping rule activation and independent tests.
-- No permissive policies: ordinary application access is intentionally deny-by-default.
